using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
internal sealed class GuidePreparation {internal int Total,Ready,Failed;internal string Current="";internal List<string> Failures=new List<string>();}
internal static class GuideDownloads {
 internal static bool Available(Store store,string slug){try{var info=new FileInfo(TougliReader.CachePath(store,slug));return info.Exists&&info.Length>0&&info.Length<=TougliReader.MaxBytes;}catch{return false;}}
 internal static async Task<GuidePreparation> Prepare(Store store,List<TougliGuideInfo> guides,Func<TougliGuideInfo,CancellationToken,Task<string>> fetch,Action<GuidePreparation> progress,CancellationToken token,int delay=100){var result=new GuidePreparation{Total=guides.Count,Ready=guides.Count(g=>Available(store,g.Slug))};progress(result);foreach(var guide in guides.Where(g=>!Available(store,g.Slug))){token.ThrowIfCancellationRequested();result.Current=guide.Title;progress(result);try{string raw=await fetch(guide,token);token.ThrowIfCancellationRequested();TougliDocument doc=GanymedeReader.IsGuide(guide.Slug)?GanymedeReader.Parse(raw,guide.Slug):TougliReader.Parse(raw,new DofusCharacter{guide=guide.Slug});if(doc.Slug!=guide.Slug)throw new InvalidDataException("Guide inattendu.");TougliReader.Cache(store,guide.Slug,raw);result.Ready++;}catch(OperationCanceledException){throw;}catch{result.Failed++;result.Failures.Add(guide.Slug);}progress(result);if(delay>0)await Task.Delay(delay,token);}return result;}
 internal static void Test(string folder){var store=new Store(Path.Combine(folder,"download-data"));var guides=new List<TougliGuideInfo>{new TougliGuideInfo{Slug="parcours-exemple",Title="Exemple"}};int requests=0;Func<TougliGuideInfo,CancellationToken,Task<string>> fetch=(g,t)=>{requests++;return Task.FromResult(StandaloneTests.Sample);};var result=Prepare(store,guides,fetch,p=>{},CancellationToken.None,0).GetAwaiter().GetResult();if(result.Ready!=1||result.Failed!=0||requests!=1)throw new Exception("Préchargement complet");Prepare(store,guides,fetch,p=>{},CancellationToken.None,0).GetAwaiter().GetResult();if(requests!=1)throw new Exception("Guide retéléchargé inutilement");var failed=Prepare(store,new List<TougliGuideInfo>{new TougliGuideInfo{Slug="autre-guide",Title="Autre"}},fetch,p=>{},CancellationToken.None,0).GetAwaiter().GetResult();if(failed.Failed!=1||Available(store,"autre-guide"))throw new Exception("Un guide manquant a été annoncé prêt");bool cancelled=false;try{Prepare(store,new List<TougliGuideInfo>{new TougliGuideInfo{Slug="annule",Title="Annulé"}},fetch,p=>{},new CancellationToken(true),0).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}if(!cancelled||!Available(store,"parcours-exemple"))throw new Exception("Reprise du téléchargement");}
}
